-- interview-fix-diagrams.sql — 補回 q5/q6/q13 被剝掉的電路圖（zh + en）
-- 背景：interview-questions-seed.sql 抽取時 SVG 被剝掉，DB 只剩空的
--       <div class="exam-diagram-box"></div>；ja/ko（interview-i18n.sql）反而有圖。
-- 產生器：scratchpad/gen-fix-diagrams.js（來源 = interview-bank.js，已上線驗證過的圖）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。
--       可重複執行：marker 被換掉後 replace() 找不到目標，第二次跑不會有副作用。

-- q5：IO 輸出架構：Push-Pull vs Open-Drain（SVG 2777 chars）
update public.interview_questions
   set answer    = replace(answer,    $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 560 200" xmlns="http://www.w3.org/2000/svg"><rect width="560" height="200" fill="#0a0a1a"/><text x="140" y="20" fill="#00d4ff" font-size="12" text-anchor="middle" font-weight="bold">Push-Pull</text><text x="420" y="20" fill="#ffc107" font-size="12" text-anchor="middle" font-weight="bold">Open-Drain</text><line x1="140" y1="30" x2="140" y2="50" stroke="#ff6b6b" stroke-width="1.5"/><text x="155" y="42" fill="#ff6b6b" font-size="9">VDD</text><rect x="125" y="50" width="30" height="20" rx="3" fill="none" stroke="#00ff88" stroke-width="1.5"/><text x="140" y="64" fill="#00ff88" font-size="8" text-anchor="middle">P</text><line x1="140" y1="70" x2="140" y2="90" stroke="#ffc107" stroke-width="2"/><circle cx="140" cy="90" r="3" fill="#ffc107"/><text x="160" y="93" fill="#ffc107" font-size="9">OUT</text><line x1="140" y1="90" x2="140" y2="110" stroke="#ffc107" stroke-width="2"/><rect x="125" y="110" width="30" height="20" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="140" y="124" fill="#00d4ff" font-size="8" text-anchor="middle">N</text><line x1="140" y1="130" x2="140" y2="150" stroke="#888" stroke-width="1.5"/><text x="155" y="148" fill="#888" font-size="9">GND</text><line x1="95" y1="90" x2="125" y2="60" stroke="#888" stroke-width="1" stroke-dasharray="3"/><line x1="95" y1="90" x2="125" y2="120" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="80" y="93" fill="#888" font-size="9">IN</text><text x="80" y="170" fill="#00ff88" font-size="9">H→VDD, L→GND</text><text x="80" y="185" fill="#888" font-size="8">主動推拉驅動</text><line x1="420" y1="30" x2="420" y2="50" stroke="#ff6b6b" stroke-width="1.5"/><text x="435" y="42" fill="#ff6b6b" font-size="9">VDD</text><rect x="410" y="50" width="20" height="35" rx="2" fill="none" stroke="#ff6b6b" stroke-width="1.5"/><text x="420" y="72" fill="#ff6b6b" font-size="8" text-anchor="middle">Rp</text><line x1="420" y1="85" x2="420" y2="100" stroke="#ffc107" stroke-width="2"/><circle cx="420" cy="100" r="3" fill="#ffc107"/><text x="440" y="103" fill="#ffc107" font-size="9">OUT</text><line x1="420" y1="100" x2="420" y2="115" stroke="#ffc107" stroke-width="2"/><rect x="405" y="115" width="30" height="20" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="420" y="129" fill="#00d4ff" font-size="8" text-anchor="middle">N</text><line x1="420" y1="135" x2="420" y2="150" stroke="#888" stroke-width="1.5"/><text x="435" y="148" fill="#888" font-size="9">GND</text><line x1="380" y1="125" x2="405" y2="125" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="365" y="128" fill="#888" font-size="9">IN</text><text x="360" y="170" fill="#ffc107" font-size="9">H→Rp上拉, L→GND</text><text x="360" y="185" fill="#888" font-size="8">需外部上拉，支持 Wire-AND</text></svg></div>$vsq$),
       answer_en = replace(answer_en, $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 560 200" xmlns="http://www.w3.org/2000/svg"><rect width="560" height="200" fill="#0a0a1a"/><text x="140" y="20" fill="#00d4ff" font-size="12" text-anchor="middle" font-weight="bold">Push-Pull</text><text x="420" y="20" fill="#ffc107" font-size="12" text-anchor="middle" font-weight="bold">Open-Drain</text><line x1="140" y1="30" x2="140" y2="50" stroke="#ff6b6b" stroke-width="1.5"/><text x="155" y="42" fill="#ff6b6b" font-size="9">VDD</text><rect x="125" y="50" width="30" height="20" rx="3" fill="none" stroke="#00ff88" stroke-width="1.5"/><text x="140" y="64" fill="#00ff88" font-size="8" text-anchor="middle">P</text><line x1="140" y1="70" x2="140" y2="90" stroke="#ffc107" stroke-width="2"/><circle cx="140" cy="90" r="3" fill="#ffc107"/><text x="160" y="93" fill="#ffc107" font-size="9">OUT</text><line x1="140" y1="90" x2="140" y2="110" stroke="#ffc107" stroke-width="2"/><rect x="125" y="110" width="30" height="20" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="140" y="124" fill="#00d4ff" font-size="8" text-anchor="middle">N</text><line x1="140" y1="130" x2="140" y2="150" stroke="#888" stroke-width="1.5"/><text x="155" y="148" fill="#888" font-size="9">GND</text><line x1="95" y1="90" x2="125" y2="60" stroke="#888" stroke-width="1" stroke-dasharray="3"/><line x1="95" y1="90" x2="125" y2="120" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="80" y="93" fill="#888" font-size="9">IN</text><text x="80" y="170" fill="#00ff88" font-size="9">H→VDD, L→GND</text><text x="80" y="185" fill="#888" font-size="8">主動推拉驅動</text><line x1="420" y1="30" x2="420" y2="50" stroke="#ff6b6b" stroke-width="1.5"/><text x="435" y="42" fill="#ff6b6b" font-size="9">VDD</text><rect x="410" y="50" width="20" height="35" rx="2" fill="none" stroke="#ff6b6b" stroke-width="1.5"/><text x="420" y="72" fill="#ff6b6b" font-size="8" text-anchor="middle">Rp</text><line x1="420" y1="85" x2="420" y2="100" stroke="#ffc107" stroke-width="2"/><circle cx="420" cy="100" r="3" fill="#ffc107"/><text x="440" y="103" fill="#ffc107" font-size="9">OUT</text><line x1="420" y1="100" x2="420" y2="115" stroke="#ffc107" stroke-width="2"/><rect x="405" y="115" width="30" height="20" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="420" y="129" fill="#00d4ff" font-size="8" text-anchor="middle">N</text><line x1="420" y1="135" x2="420" y2="150" stroke="#888" stroke-width="1.5"/><text x="435" y="148" fill="#888" font-size="9">GND</text><line x1="380" y1="125" x2="405" y2="125" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="365" y="128" fill="#888" font-size="9">IN</text><text x="360" y="170" fill="#ffc107" font-size="9">H→Rp上拉, L→GND</text><text x="360" y="185" fill="#888" font-size="8">需外部上拉，支持 Wire-AND</text></svg></div>$vsq$)
