-- q13：Buck 上管 ON / OFF 電流路徑（SVG 2901 chars）
update public.interview_questions
   set answer    = replace(answer,    $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 560 200" xmlns="http://www.w3.org/2000/svg"><rect width="560" height="200" fill="#0a0a1a"/><text x="140" y="18" fill="#00d4ff" font-size="11" text-anchor="middle" font-weight="bold">Phase 1: HS ON</text><text x="420" y="18" fill="#ffc107" font-size="11" text-anchor="middle" font-weight="bold">Phase 2: HS OFF</text><text x="40" y="45" fill="#ff6b6b" font-size="9">VIN</text><rect x="60" y="35" width="40" height="20" rx="3" fill="none" stroke="#00ff88" stroke-width="1.5"/><text x="80" y="49" fill="#00ff88" font-size="8" text-anchor="middle">HS ON</text><line x1="100" y1="45" x2="130" y2="45" stroke="#ffc107" stroke-width="2"/><path d="M 130 45 Q 140 35 150 45 Q 160 55 170 45" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="150" y="65" fill="#00d4ff" font-size="8" text-anchor="middle">L</text><line x1="170" y1="45" x2="200" y2="45" stroke="#ffc107" stroke-width="2"/><rect x="200" y="35" width="30" height="20" rx="3" fill="none" stroke="#ff6b6b" stroke-width="1"/><text x="215" y="49" fill="#ff6b6b" font-size="7" text-anchor="middle">Load</text><path d="M 55 45 L 230 45" stroke="#00ff88" stroke-width="0" fill="none"/><text x="140" y="82" fill="#00ff88" font-size="9" text-anchor="middle">→ VIN → HS → L → Load →</text><rect x="95" y="90" width="40" height="15" rx="3" fill="none" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="115" y="101" fill="#888" font-size="7" text-anchor="middle">LS OFF</text><text x="320" y="45" fill="#888" font-size="9">VIN</text><rect x="340" y="35" width="40" height="20" rx="3" fill="none" stroke="#888" stroke-width="1.5" stroke-dasharray="3"/><text x="360" y="49" fill="#888" font-size="8" text-anchor="middle">HS OFF</text><line x1="380" y1="45" x2="410" y2="45" stroke="#ffc107" stroke-width="2"/><path d="M 410 45 Q 420 35 430 45 Q 440 55 450 45" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="430" y="65" fill="#00d4ff" font-size="8" text-anchor="middle">L</text><line x1="450" y1="45" x2="480" y2="45" stroke="#ffc107" stroke-width="2"/><rect x="480" y="35" width="30" height="20" rx="3" fill="none" stroke="#ff6b6b" stroke-width="1"/><text x="495" y="49" fill="#ff6b6b" font-size="7" text-anchor="middle">Load</text><rect x="375" y="90" width="40" height="15" rx="3" fill="none" stroke="#ffc107" stroke-width="1.5"/><text x="395" y="101" fill="#ffc107" font-size="7" text-anchor="middle">LS ON</text><text x="420" y="130" fill="#ffc107" font-size="9" text-anchor="middle">→ GND → LS → L → Load →</text><text x="140" y="155" fill="#00d4ff" font-size="9" text-anchor="middle">IL waveform (CCM)</text><line x1="40" y1="185" x2="250" y2="185" stroke="#444" stroke-width="1"/><path d="M 40 185 L 140 165 L 250 185" fill="none" stroke="#00ff88" stroke-width="2"/><text x="90" y="163" fill="#00ff88" font-size="8">↑ charge</text><text x="195" y="163" fill="#ff6b6b" font-size="8">↓ discharge</text></svg></div>$vsq$),
       answer_en = replace(answer_en, $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 560 200" xmlns="http://www.w3.org/2000/svg"><rect width="560" height="200" fill="#0a0a1a"/><text x="140" y="18" fill="#00d4ff" font-size="11" text-anchor="middle" font-weight="bold">Phase 1: HS ON</text><text x="420" y="18" fill="#ffc107" font-size="11" text-anchor="middle" font-weight="bold">Phase 2: HS OFF</text><text x="40" y="45" fill="#ff6b6b" font-size="9">VIN</text><rect x="60" y="35" width="40" height="20" rx="3" fill="none" stroke="#00ff88" stroke-width="1.5"/><text x="80" y="49" fill="#00ff88" font-size="8" text-anchor="middle">HS ON</text><line x1="100" y1="45" x2="130" y2="45" stroke="#ffc107" stroke-width="2"/><path d="M 130 45 Q 140 35 150 45 Q 160 55 170 45" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="150" y="65" fill="#00d4ff" font-size="8" text-anchor="middle">L</text><line x1="170" y1="45" x2="200" y2="45" stroke="#ffc107" stroke-width="2"/><rect x="200" y="35" width="30" height="20" rx="3" fill="none" stroke="#ff6b6b" stroke-width="1"/><text x="215" y="49" fill="#ff6b6b" font-size="7" text-anchor="middle">Load</text><path d="M 55 45 L 230 45" stroke="#00ff88" stroke-width="0" fill="none"/><text x="140" y="82" fill="#00ff88" font-size="9" text-anchor="middle">→ VIN → HS → L → Load →</text><rect x="95" y="90" width="40" height="15" rx="3" fill="none" stroke="#888" stroke-width="1" stroke-dasharray="3"/><text x="115" y="101" fill="#888" font-size="7" text-anchor="middle">LS OFF</text><text x="320" y="45" fill="#888" font-size="9">VIN</text><rect x="340" y="35" width="40" height="20" rx="3" fill="none" stroke="#888" stroke-width="1.5" stroke-dasharray="3"/><text x="360" y="49" fill="#888" font-size="8" text-anchor="middle">HS OFF</text><line x1="380" y1="45" x2="410" y2="45" stroke="#ffc107" stroke-width="2"/><path d="M 410 45 Q 420 35 430 45 Q 440 55 450 45" fill="none" stroke="#00d4ff" stroke-width="1.5"/><text x="430" y="65" fill="#00d4ff" font-size="8" text-anchor="middle">L</text><line x1="450" y1="45" x2="480" y2="45" stroke="#ffc107" stroke-width="2"/><rect x="480" y="35" width="30" height="20" rx="3" fill="none" stroke="#ff6b6b" stroke-width="1"/><text x="495" y="49" fill="#ff6b6b" font-size="7" text-anchor="middle">Load</text><rect x="375" y="90" width="40" height="15" rx="3" fill="none" stroke="#ffc107" stroke-width="1.5"/><text x="395" y="101" fill="#ffc107" font-size="7" text-anchor="middle">LS ON</text><text x="420" y="130" fill="#ffc107" font-size="9" text-anchor="middle">→ GND → LS → L → Load →</text><text x="140" y="155" fill="#00d4ff" font-size="9" text-anchor="middle">IL waveform (CCM)</text><line x1="40" y1="185" x2="250" y2="185" stroke="#444" stroke-width="1"/><path d="M 40 185 L 140 165 L 250 185" fill="none" stroke="#00ff88" stroke-width="2"/><text x="90" y="163" fill="#00ff88" font-size="8">↑ charge</text><text x="195" y="163" fill="#ff6b6b" font-size="8">↓ discharge</text></svg></div>$vsq$)
 where question like $q$%Buck 轉換器的電流路徑圖%$q$;

-- 驗收：三列都要 zh_has_svg = t 且 en_has_svg = t，empty_box_left = f
select id, left(question, 24) as q,
       answer    like '%<svg%' as zh_has_svg,
       answer_en like '%<svg%' as en_has_svg,
       (answer like $box$%<div class="exam-diagram-box"></div>%$box$ or answer_en like $box$%<div class="exam-diagram-box"></div>%$box$) as empty_box_left
  from public.interview_questions
 where question like $q$%Open-Drain 與 Push-Pull%$q$
    or question like $q$%I2C Bus 介面配線圖%$q$
    or question like $q$%Buck 轉換器的電流路徑圖%$q$;
